examples.code:
.card {
  width: 320px;              /* контентная область, если box-sizing не менять */
  padding: 20px;             /* внутреннее поле, фон закрашивает и его */
  border: 1px solid #2a3350;
  margin: 0 auto;            /* центрирование блока по горизонтали */
  outline: 3px solid #6366f1; /* поверх рамки, места в раскладке не занимает */
}

/* два значения — вертикаль и горизонталь, четыре — по часовой стрелке */
.toolbar { margin: 12px 24px; padding: 8px 12px 10px 16px; }

